"290 :   private boolean isVariableStillLiveWithinExpression(
291 :       Node n, Node exprRoot, String variable) {
292 :     while (n != exprRoot) {
293 :       VariableLiveness state = VariableLiveness.MAYBE_LIVE;
294 :       switch (n.getParent().getType()) {
295 :         case Token.OR:
296 :         case Token.AND:
297 :           // If the currently node is the first child of
298 :           // AND/OR, be conservative only consider the READs
299 :           // of the second operand.
300 : 
301 :         case Token.HOOK:
302 :           // If current node is the condition, check each following
303 :           // branch, otherwise it is a conditional branch and the
304 :           // other branch can be ignored.
305 : 
306 :         default:
307 :           for(Node sibling = n.getNext(); sibling != null;
308 :               sibling = sibling.getNext()) {
309 :             if (!ControlFlowGraph.isEnteringNewCfgNode(sibling)) {
310 :             state = isVariableReadBeforeKill(sibling, variable);
311 : 
312 :       // If we see a READ or KILL there is no need to continue.
313 :       if (state == VariableLiveness.READ) {
314 :         return true;
315 :       } else if (state == VariableLiveness.KILL) {
316 :         return false;
317 :             }
318 :           }
319 :       }
320 :       }
321 :       n = n.getParent();
322 :     }
323 :     return false;
324 :   }"

"338 :   private VariableLiveness isVariableReadBeforeKill(
339 :       Node n, String variable) {
340 : 
341 :     if (NodeUtil.isName(n) && variable.equals(n.getString())) {
342 :       if (NodeUtil.isLhs(n, n.getParent())) {
343 :         Preconditions.checkState(n.getParent().getType() == Token.ASSIGN);
344 :         // The expression to which the assignment is made is evaluated before
345 :         // the RHS is evaluated (normal left to right evaluation) but the KILL
346 :         // occurs after the RHS is evaluated.
347 :         Node rhs = n.getNext();
348 :         VariableLiveness state = isVariableReadBeforeKill(rhs, variable);
349 :         if (state == VariableLiveness.READ) {
350 :           return state;
351 :         }
352 :         return VariableLiveness.KILL;
353 :       } else {
354 :         return VariableLiveness.READ;
355 :       }
356 :     }
357 : 
358 :     switch (n.getType()) {
359 :       // Conditionals
360 :       case Token.OR:
361 :       case Token.AND:
362 :         // With a AND/OR the first branch always runs, but the second is
363 :         // may not.
364 :       case Token.HOOK:
365 :         return checkHookBranchReadBeforeKill(
366 :             n.getFirstChild().getNext(), n.getLastChild(), variable);
367 : 
368 :       default:
369 :         // Expressions are evaluated left-right, depth first.
370 :         for (Node child = n.getFirstChild();
371 :             child != null; child = child.getNext()) {
372 :           if (!ControlFlowGraph.isEnteringNewCfgNode(child)) { // Not a FUNCTION
373 :           VariableLiveness state = isVariableReadBeforeKill(child, variable);
374 :           if (state != VariableLiveness.MAYBE_LIVE) {
375 :             return state;
376 :           }
377 :         }
378 :       }
379 :     }
380 : 
381 :     return VariableLiveness.MAYBE_LIVE;
382 :   }"

"384 :   private VariableLiveness checkHookBranchReadBeforeKill(
385 :       Node trueCase, Node falseCase, String variable) {
386 :     VariableLiveness v1 = isVariableReadBeforeKill(
387 :       trueCase, variable);
388 :     VariableLiveness v2 = isVariableReadBeforeKill(
389 :       falseCase, variable);
390 :     // With a hook it is unknown which branch will run, so
391 :     // we must be conservative.  A read by either is a READ, and
392 :     // a KILL is only considered if both KILL.
393 :     if (v1 == VariableLiveness.READ || v2 == VariableLiveness.READ) {
394 :       return VariableLiveness.READ;
395 :     } else if (v1 == VariableLiveness.KILL && v2 == VariableLiveness.KILL) {
396 :       return VariableLiveness.KILL;
397 :     } else {
398 :       return VariableLiveness.MAYBE_LIVE;
399 :     }
400 :   }"

